#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// 프로젝트 디렉토리에서 git 정보 수집
const projectsDir = '/tmp/freelang-project-excellence/.projects';
const projects = [];

if (fs.existsSync(projectsDir)) {
  const dirs = fs.readdirSync(projectsDir);

  for (const dir of dirs) {
    const projectPath = path.join(projectsDir, dir);
    if (fs.statSync(projectPath).isDirectory()) {
      try {
        // git log 체크 (커밋 있는지)
        const { execSync } = require('child_process');
        const commits = execSync(`cd "${projectPath}" && git rev-list --count HEAD 2>/dev/null || echo 0`, { encoding: 'utf8' }).trim();
        projects.push({
          name: dir,
          commits: parseInt(commits) || 0,
          path: projectPath
        });
      } catch (e) {
        // 에러 무시
      }
    }
  }
}

console.log('\n📊 전체 프로젝트 포트폴리오 분석\n');
console.log(`발견된 프로젝트: ${projects.length}개\n`);

// 통계 계산
const totalCommits = projects.reduce((sum, p) => sum + p.commits, 0);
const avgCommits = projects.length > 0 ? (totalCommits / projects.length).toFixed(1) : 0;

// 활동도별 분류
const active = projects.filter(p => p.commits > 20);
const moderate = projects.filter(p => p.commits >= 6 && p.commits <= 20);
const lowActivity = projects.filter(p => p.commits >= 1 && p.commits < 6);
const archived = projects.filter(p => p.commits === 0);

console.log(`총 커밋: ${totalCommits.toLocaleString()}개`);
console.log(`평균: ${avgCommits}개/프로젝트\n`);

console.log('📈 활동도별 분류:');
console.log(`  고활동 (20+ commits): ${active.length}개 (${(active.length/projects.length*100).toFixed(1)}%)`);
console.log(`  중활동 (6-20 commits): ${moderate.length}개 (${(moderate.length/projects.length*100).toFixed(1)}%)`);
console.log(`  저활동 (1-5 commits): ${lowActivity.length}개 (${(lowActivity.length/projects.length*100).toFixed(1)}%)`);
console.log(`  휴지 (0 commits): ${archived.length}개 (${(archived.length/projects.length*100).toFixed(1)}%)\n`);

// 상위 15개 프로젝트
const top15 = projects.sort((a, b) => b.commits - a.commits).slice(0, 15);
console.log('🏆 상위 15개 프로젝트:');
top15.forEach((p, i) => {
  console.log(`${(i+1).toString().padStart(2)}. ${p.name.padEnd(40)} ${p.commits.toString().padStart(4)} commits`);
});

EOF
node analyze-portfolio.js
